window.LD=window.LD||{};window.LD["hero/h11"]={"id":"h11","name":"Natasha","owner":"Natasha","npc":false,"pronoun":"she","cls":"paladin","title":"Paladin","level":11,"look":{"skin":"#c98e62","hair":"#4b2e1e","style":1,"face":0,"fav":"#d860a8","fav_name":"pink","scars":[]},"pet":null,"mount":null,"alive":true,"keepsake":"an old map of Goblin Camp","maps":[{"dungeon":"ashveil_crypts","pct":40,"worked":13}],"party":"p2","party_name":"The Verdant Sigil","loc":"bleakmarsh","loc_name":"Bleakmarsh","travel":null,"rep":{"ironhaven":2,"thornwall":3,"carrbridge":1,"ashfen":15},"curse":null,"fstanding":{"dawn":14.0,"collegium":2.0,"fellowship":-4.0,"scale":2.0,"thorns":-1.5},"faction":null,"frank":0,"doing":"hunting in Bleakmarsh","why":"paid to clear 10 will-o'-wisps out of Bleakmarsh","delve":{"now":null,"last":{"dest":"ashveil_crypts","day":22,"days":7,"why":"after the boss: about 21 silver a day each, risk slight; the season goal: to earn 1,150 silver between them before the season ends","packed":{"torches":33,"rations":33},"turn":"their nerves were fraying","rooms":13}},"route":"Day 28: spent the day in Bleakmarsh.","today":["Hunted all day without turning up a fight.","+24 XP.","Coin: +4 silver.","Foraged a bundle of herbs.","Ate a ration.","New gear: Sunflash Sigil.","Stress: +5 a day's hunting, +2 camping out, −1 good company, −1 an omen."],"fights_today":[],"tables_today":[],"daybook":{"day":28,"label":"Day 28","title":"Season 1, day 28, hour by hour","blocks":[{"act":"hunt","label":"Reading the ground","from":6.0,"to":7.0,"line":"Natasha finds a tuft of hair on a snag and holds it up for Echo. Echo pushes into the thicket after the drag marks, thorns and all, and finds where something big has cached a kill under the brush. Its owner is close.","stretch":"sign","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"rec":"r129","event":"hx_sign_drag","branch":"thicket"},{"act":"hunt","label":"Reading the ground","from":7.0,"to":10.0,"line":"Natasha keeps quiet and lets Echo think, which is a skill of its own. Echo pulls a tuft of fur from a bramble and builds a fine theory around it. The tuft comes from her own pack.","stretch":"sign","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"event":"hs_track_hair","test":"bad"},{"act":"hunt","label":"The stalk","from":10.0,"to":11.0,"line":"Natasha strips off the boots and wades. The cold is a living thing, and the far bank is an untouched stretch of game country. Why: Natasha is bold.","stretch":"stalk","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"rec":"r130","event":"hx_stalk_ford","branch":"wade"},{"act":"hunt","label":"The stalk","from":11.0,"to":13.0,"line":"Natasha takes the low ground so Christian can keep the high. The frogs stop all at once. In the new silence Christian can hear the water moving where nothing should move it.","stretch":"stalk","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"event":"hw_bm_croak"},{"act":"hunt","label":"The quarry","from":13.0,"to":16.0,"line":"Echo holds the line at the stream while Natasha walks the herd up towards it, and the plan works. A pelt, and a nod between them.","stretch":"quarry","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"event":"hq_crew_drive"},{"act":"hunt","label":"Dressing the kill","from":16.0,"to":17.0,"line":"Natasha lays out the cloth and the salt, and waits to be useful. Christian stretches the skin of the beast between two saplings and scrapes until the arms ache. By full dark a pelt is salted and rolled.","stretch":"dress","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"event":"hc_dress_frame"},{"act":"hunt","label":"Making camp","from":17.0,"to":18.0,"line":"Natasha gets the fire going at the edge of Bleakmarsh and sits with her back to a tree, listening to the dark come in.","stretch":"camp","biome":"marsh","weather":"cloudy","crew":["h11","h6","h19"],"event":"hc_camp_fire"}],"evening":{"kind":"camp","line":"Camped out in Bleakmarsh"},"wday":28},"grew":[],"progress":"day 3 of 7","goal":{"text":"to earn 1,150 silver between them before the season ends","kind":"purse","done":null,"progress":"360 of 1,150 silver","missed":false,"crew":"The Verdant Sigil","party":"p2"},"vows":[],"renown":187,"epithet":"Everyone's-Friend","gold":106,"copper":0,"hp":116,"maxhp":116,"injuries":[],"legend":false,"weapon":"sword","weapon_tier":1,"armor":"chain","armor_tier":1,"kit":{"weapon":{"family":"sword","tier":1,"two":false,"glow":null},"offhand":{"art":"holy_symbol","tier":2,"glow":"#fff4a0"},"armor":{"material":"chain","tier":1,"outfit":"chain","glow":null},"head":{"art":"helm","tier":1,"glow":null},"back":null,"neck":null,"rings":[],"pocket":null,"belt":null,"boots":null,"gloves":null,"mark":"tabard"},"vox":{"bold":0.14,"style":"bubbly"},"jail":0,"away":false,"died_day":null,"died_season":null,"died_sday":null,"joined":1,"lodging":"suite","power":147,"home":null,"sleep":{"setting":"camp","place":"Camped out at Bleakmarsh"},"dream":"to write a song","god":{"stance":"keeps","patron":"aurel","devoted":null,"mark":null,"token":null},"trophies":[{"boss":"Gruk the Warchief","monster":"goblin_warchief","gen":1,"role":null,"place":"Goblin Camp","day":9,"season":1,"fight":"f25","with":"The Verdant Sigil"}],"cabinet":[],"stats":{"might":15,"agility":9,"mind":13,"grit":6,"heart":17},"eff":{"might":15,"agility":9,"mind":13,"grit":6,"heart":17},"traits":{"boldness":0.138,"risk":0.09,"greed":-0.69,"sociability":0.25,"honor":0.69,"curiosity":0.3,"temper":-0.07,"loyalty":-0.3},"aff":{"travel":2.1,"command":2.1,"beast":0.1,"heal":2.6,"guard":0.0,"holy":8.0,"music":0.8,"lore":0.1,"crit":0.0,"stealth":0.0,"trade":0.3,"hunt":0.7,"craft":0.3,"fate":1.5,"nature":0.6},"lean_aff":{"travel":1.3,"command":2.0,"beast":0.1,"heal":2.2,"guard":0.0,"holy":7.0,"music":0.8,"lore":0.0,"crit":0.0,"stealth":0.0,"trade":0.1,"hunt":1.2,"craft":0.5,"fate":1.9,"nature":0.7},"growth":{"might":2.5,"agility":1.15,"mind":1.75,"grit":1.3,"heart":1.6},"skills":[{"id":"field_dressing","rank":1,"name":"Field Dressing","desc":"Moss, spit and a clean-ish rag.","tags":["heal"],"type":"heal","uses":2,"school":"healing","side":false,"own":false,"keystone":null},{"id":"stray_magnet","rank":1,"name":"Stray Magnet","desc":"Every stray in town follows them home.","tags":[],"type":"world","uses":0,"school":"beast","side":true,"own":false,"keystone":null},{"id":"sermoniser","rank":1,"name":"Sermoniser","desc":"Has a sermon for every occasion, including this one.","tags":["holy"],"type":"world","uses":0,"school":"holy","side":false,"own":true,"keystone":null},{"id":"peacemaker","rank":1,"name":"Peacemaker","desc":"Stops the argument before it gets to the swords.","tags":["command","holy"],"type":"world","uses":0,"school":"command","side":false,"own":false,"keystone":null},{"id":"aura_of_courage","rank":1,"name":"Aura of Courage","desc":"Nobody runs while they stand.","tags":["holy","command"],"type":"passive","uses":0,"school":"holy","side":false,"own":false,"keystone":null},{"id":"tooth_puller","rank":1,"name":"Tooth Puller","desc":"Village dentist. Steady hand, strong string.","tags":["heal"],"type":"world","uses":0,"school":"healing","side":false,"own":false,"keystone":null},{"id":"smite","rank":1,"name":"Smite","desc":"Radiant and righteous. Double against the dead.","tags":["holy"],"type":"attack","uses":4,"school":"holy","side":false,"own":false,"keystone":null},{"id":"pilgrim","rank":1,"name":"Pilgrim","desc":"Every road leads to a shrine, if you walk it right.","tags":["holy","travel"],"type":"world","uses":0,"school":"holy","side":false,"own":false,"keystone":null},{"id":"radiance","rank":1,"name":"Radiance","desc":"A flash of holy light, right in the eyes.","tags":["holy"],"type":"attack","uses":1,"school":"holy","side":false,"own":true,"keystone":null},{"id":"pilgrims_escort","rank":1,"name":"The Pilgrims' Escort","desc":"Never walks a road alone. Rarely walks it without a hymn.","tags":[],"type":"world","uses":2,"school":null,"side":false,"own":false,"keystone":10,"does":"On travel days she often sees strangers safely on their way, for silver and experience."},{"id":"oath_of_light","rank":1,"name":"Oath of Light","desc":"Says the oath before the first blow. The oath is long. The armour holds.","tags":["holy"],"type":"trigger","uses":2,"school":"holy","side":false,"own":true,"keystone":null},{"id":"second_breakfast","rank":1,"name":"Second Breakfast","desc":"Eats a sausage mid-fight. Feels much better.","tags":[],"type":"self_heal","uses":0,"school":"hearth","side":true,"own":false,"keystone":null}],"kit_items":[{"slot":"weapon","name":"Rusty Sword","art":"sword","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"","story":null,"day":null,"history":[],"plus":"hits harder on every blow (+5 power)"},{"slot":"armor","name":"Rusty Mail","art":"chain","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"","story":null,"day":null,"history":[],"plus":"harder to hurt (+5 armour)"},{"slot":"offhand","name":"Sunflash Sigil","art":"holy_symbol","tier":null,"gem":null,"tint":"#e8c040","glow":"#fff4a0","magic":true,"enchant":null,"desc":"A polished golden sun. When its bearer prays hard enough, it catches a light that isn't there and throws it in the enemy's eyes.","fx":"Now and then blinds foes","story":"A gift from Ankit","day":28,"history":[{"day":17,"text":"Found in Cragtooth Warren, by Mark"},{"day":18,"text":"Named at the Academy"},{"day":18,"text":"Given by Mark to Ankit"},{"day":18,"text":"First worn by Ankit"},{"day":28,"text":"Given by Ankit to Natasha"},{"day":28,"text":"First worn by Natasha"}],"plus":null},{"slot":"head","name":"Nasal Helm","art":"helm","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"A little better protected (+1 armour)","story":"Bought in Ironhaven","day":1,"history":[],"plus":"harder to hurt (+1 armour)"}],"row":"front","curios":[],"sets":[{"name":"Good Dog Tarot","kind":"tarot","tier":1,"art":"cards","desc":"A Carrbridge fair deck in which every figure is a dog, from the Fool's terrier to the spaniel Queen of Cups.","look":"Storybook gouache in a brick-red frame, every figure a dog, a bone for a name-plate","condition":"like new","missing":0,"games":1,"story":"Bought in Carrbridge for 12 silver","history":[{"day":12,"text":"Bought in Carrbridge for 12 silver, by Natasha"}]}],"h2h":{"rows":[],"prefs":{"cards":0.1622,"dice":0.0152,"checkers":0.0749,"chess":0.1742,"tarot":0.5735},"nicks":{}},"pastimes":{"keen":{"sing":0.517,"play":0.2,"cook":0.408,"fish":0.075,"game":0.611},"skill":{"sing":0.471,"play":0.0,"cook":0.17,"fish":0.0,"game":0.401}},"purse":[[1,210,null],[2,210,{}],[3,130,{"rations":-20,"busking":10,"beds":-70}],[4,110,null],[5,140,{"loot":30}],[6,180,{"loot":40}],[7,180,{}],[8,400,{"treasure":220}],[9,780,{"loot":280,"boss":100}],[10,880,{"maps sold":100}],[11,570,{"sales":80,"bounties":120,"rations":-100,"potions":-160,"gear":-110,"tavern":-70,"beds":-70}],[12,272,{"rations":-200,"goods":-10,"food":-8,"sales":100,"hobbies":-120,"beds":-60}],[13,264,{"food":-8}],[14,194,{"food":-10,"tavern":-20,"beds":-40}],[15,164,{"bath":-30}],[16,164,{}],[17,164,{}],[18,164,{}],[19,164,{}],[20,164,{}],[21,574,{"treasure":410}],[22,834,{"apply":260}],[23,1108,{"sales":520,"rations":-10,"bath":-30,"tavern":-70,"food":-36,"beds":-100}],[24,926,{"food":-42,"tavern":-70,"beds":-80,"apply":10}],[25,780,{"rations":-140,"readings":-6}],[26,780,{}],[27,1020,{"apply":240}],[28,1060,{"old kit sold":40}]],"music":{"band":0.471,"label":"decent","inst":[],"songs":[{"src":"folk","id":"footbridge_dance","title":"The Footbridge Dance","tone":"rowdy","meter":"4/4","bpm":112,"diff":2,"n":1},{"src":"folk","id":"miners_daughter","title":"The Miner's Daughter","tone":"sad","meter":"3/4","bpm":100,"diff":2,"n":1},{"src":"book","id":"heron_king","title":"The Heron King","tone":"odd","meter":"6/8","bpm":97,"diff":4,"n":1}],"wrote":[],"played":3.25,"n":{"led":2,"sore":1,"joined":1},"anthem":null,"moments":[],"lately":[{"id":"n20","day":22,"title":"The Footbridge Dance","src":"folk","role":"sing","outcome":"sweet","where":"camp","place":"camp in The Ashveil Crypts","lead":"h6"},{"id":"n15","day":20,"title":"The Miner's Daughter","src":"folk","role":"led","outcome":"mess","where":"camp","place":"camp in The Ashveil Crypts","lead":"h11"}]},"omens":{"active":[{"card":"major_11_justice","name":"Justice","rev":true,"good":false,"says":"a poor bargain","tier":"plain","secret":false,"left":3,"by":"Old Marrow","reading":"r102","deck":"witch","overlay":"bog"},{"card":"major_03_empress","name":"The Empress","rev":false,"good":true,"says":"the land provides","tier":"plain","secret":false,"left":3,"by":"Old Marrow","reading":"r102","deck":"witch","overlay":"bog"},{"card":"cups_king","name":"King of Cups","rev":false,"good":true,"says":"sleeps easy","tier":"plain","secret":false,"left":3,"by":"Old Marrow","reading":"r102","deck":"witch","overlay":"bog"}],"log":[{"rid":"r33","day":14,"card":"swords_9","rev":false,"omen":"restless","hit":false,"by":"Natasha"},{"rid":"r33","day":14,"card":"major_18_moon","rev":false,"omen":"shadows","hit":false,"by":"Natasha"},{"rid":"r33","day":14,"card":"cups_3","rev":false,"omen":"welcome","hit":true,"by":"Natasha"}],"reads":{"read":1,"checked":3,"hits":1}},"table":{"favourite":"pie","favourite_name":"pies and pasties","keeps_parts":true,"cook":0.3,"cooks":true,"dishes":[{"id":"cap_ragout","name":"Walking-Cap Ragout","n":2,"love":false},{"id":"eel_pie","name":"Eel Pie","n":2,"love":true},{"id":"drake_steak","name":"Drake Steak","n":1,"love":false},{"id":"fenmist_chowder","name":"Fen-Mist Chowder","n":1,"love":false},{"id":"ransom_hotpot","name":"Stolen-Sausage Hotpot","n":1,"love":false}],"recent":[{"day":26,"meal":"m80","dish":"cap_ragout","text":"Natasha cooks some Walking-Cap Ragout in Bleakmarsh while the rest pretend to keep watch. It stopped twitching the moment the garlic went in."},{"day":24,"meal":"m71","dish":"eel_pie","text":"In the Ashfen feud over how many eels should look out of a pie, Natasha is the deciding spoon this week. The vote goes to Widow Marl. (1 silver)"},{"day":24,"meal":"m70","dish":"sea_grape_salad","text":"The market in Ashfen has a cook up from Saltmarrow today. Natasha queues for some Sea-Grape Salad on the strength of the smell alone. It pops so loudly someone checks the dark. (2 silver 4 copper)"},{"day":24,"meal":"m68","dish":"fenmist_chowder","text":"It's feast day in Ashfen, and Echo, Natasha and Christian eat some Fen-Mist Chowder at the long tables with half the town. It smells of smoke and the fen at dawn. (8 copper each)"},{"day":23,"meal":"m63","dish":"drake_steak","text":"Natasha has a Drake Steak at The Damp Lantern and sends compliments to Gilda Wetfoot. It makes the eater breathe tiny smoke rings. (3 silver 6 copper)"},{"day":18,"meal":"m51","dish":"cap_ragout","text":"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile."},{"day":17,"meal":"m42","dish":"victory_ham","text":"Gruk's Victory Ham in the Ashveil Crypts. Christian cooks it like a ceremony, and the crew eat it like one. It comes glazed on the warchief's own shield."},{"day":16,"meal":"m36","dish":"toasted_cheese","text":"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake."},{"day":14,"meal":"m29","dish":"eel_pie","text":"Natasha tastes an Eel Pie from Widow Marl, then from Tobin the eel-catcher, then from Widow Marl again to be sure, and names Tobin the eel-catcher the better. The other one takes it badly. (1 silver)"},{"day":13,"meal":"m18","dish":"ransom_hotpot","text":"The Carrbridge cook serves Stolen-Sausage Hotpot on feast day, made from what heroes sold her, and Natasha recognises some of it. It tastes of justice and fennel. (8 copper)"},{"day":12,"meal":"m16","dish":"sergeants_roast","text":"Feast day in Thornwall: Natasha finds a bench at the long tables and eats The Sergeant's Roast with strangers who are friends by the pudding. It comes with the carving shouted out slice by slice. (8 copper)"}],"knack":0.4,"cooked":[{"id":"cap_ragout","name":"Walking-Cap Ragout","n":1,"kind":"monster"},{"id":"toasted_cheese","name":"Toasted Cheese Trenchers","n":1,"kind":"camp"}]},"angler":null,"next_class":{"level":18,"id":"crusader","name":"Crusader","alt":"Saint","why":["holy work","healing"]},"travellers":[["marigold","Marigold",1]],"goals_log":[],"vow_log":[],"letters":[{"day":7,"season":1,"text":"Hi! The map was RIGHT! I stood at the mouth of Goblin Camp with it in my hand and every turn matched. Echo, Christian and I are The Verdant Sigil, and we went in. Floor 1: 4 Goblins and a Giant Rat. Floor 2: 2 Goblins and a Goblin Shaman. Before that, a fox curled up by my embers and I told everyone about it, twice. I also sang The Heron King, and Echo was very kind. Level 4! Hugs to the whole league! — Natasha","voice":"bubbly"},{"day":14,"season":1,"text":"Hi! The map was real, I tell you! A torn treasure map blew across the road to Thornwall and wrapped itself around my ankle, with Emberdeep marked on it. Honestly I felt chosen. The Verdant Sigil also settled on a goal, 1,150 silver between us, and I washed bowls at the Carrbridge poorhouse for two hours to start earning it. Then feast day: Stolen-Sausage Hotpot, made from what we sold. Christian and I had a shouting match about whose idea the last dungeon was, and I am not conceding. Hot soup wins either way. Cheers! — Natasha","voice":"bubbly"},{"day":21,"season":1,"text":"Hello, all! Level 10 and a Paladin, and Oath of Light is mine! In the choir loft of the Ashveil Crypts my Smite met a skeleton and it lay down for good: 16 bones for the pile. A bard with a cracked lute sang \"Natasha, Natasha, Bring the Silver Home\" at The Damp Lantern, all about Goblin Camp, and everyone joined in but the lute. Sad bit: the Ninth Step cracked Christian's collarbone, though he still tightened my strap mid-corridor. I showed Echo each pilgrim token and told where it came from. Big grin, — Natasha","voice":"bubbly"},{"day":28,"season":1,"text":"Big news, I'm famous! Sort of! \"Natasha, Natasha, Bring the Silver Home\" is sung in six towns now, and the bards are fighting over the rights. The silver part is true, too: I walked a pedlar and a very unlucky donkey past Bleakmarsh, carried the load half the way, learned loads about pots, and got 24 silver at the gate. Then Ankit passed me Sunflash Sigil, which began as Mark's gift to him, and I put it on at once! Grinning ear to ear, — Natasha","voice":"bubbly","links":[{"song":"s19_11"}]}],"voice":"bubbly","threads":[[{"id":"e210","day":9,"kind":"boss","text":"Down at the bottom of Goblin Camp, The Verdant Sigil slays Gruk the Warchief, a Goblin Archer and a Goblin. Echo's Pinning Shot dropped Gruk, Christian's Hammer Down tied him up, and Echo did the unglamorous work that kept the line from breaking. Loot: 6 goblin ears, 3 trinkets, Gruk's own smoked ham.","heroes":["h6","h11","h19"],"parties":["p2"],"fight":"f25"},{"id":"e228","day":9,"kind":"big_move","text":"Gruk the Warchief is down, and the table moves: Echo +56 renown (11th to 2nd), Christian +52 (10th to 3rd) and Natasha +51 (12th to 4th). The Verdant Sigil +107 party renown, 3rd to 1st among the crews.","heroes":["h6","h19","h11"],"parties":["p2"],"fight":"f25"}]],"renown_parts":[["levels",60],["deeds and stories",46],["bosses",30],["silver earned",22],["kills",13],["dungeon floors",8],["delves",5],["good deeds",2]],"class_history":[[0,"warrior"],[19,"paladin"]],"gear":{"weapon":{"slot":"weapon","family":"sword","tier":1,"name":"Rusty Sword","kind":"melee"},"armor":{"slot":"armor","family":"chain","tier":1,"name":"Rusty Mail"},"offhand":{"slot":"offhand","magic":"sunflash_sigil","name":"Sunflash Sigil","identified":true,"found_day":17,"value":150,"mods":{},"from":"A gift from Ankit","day":28,"history":[{"day":17,"text":"Found in Cragtooth Warren, by Mark"},{"day":18,"text":"Named at the Academy"},{"day":18,"text":"Given by Mark to Ankit"},{"day":18,"text":"First worn by Ankit"},{"day":28,"text":"Given by Ankit to Natasha"},{"day":28,"text":"First worn by Natasha"}],"owners":["h18","h14","h11"]},"head":{"slot":"head","family":"helm","tier":1,"name":"Nasal Helm","from":"Bought in Ironhaven","day":1},"back":null,"neck":null,"ring1":null,"ring2":null,"pocket":null,"belt":null,"boots":null,"gloves":null},"inv":{"potion":2,"torch":3,"ration":7,"crypt_cap":1,"herbs":2},"xp":372,"relics":[],"xp_next":583,"stress":7,"stress_why":[["slept in the best suite in town",-18],["camping out",10],["a night out",-8],["a night at the tavern",-6],["a day's hunting",6],["good company",-5]],"fears":["fire","rats"],"food":"wine","habits":["generous","luxury"],"hobby":"throwing parties","hobby_spent":0,"folk":{"ironhaven":{"barkeep":8},"thornwall":{"barkeep":2},"ashfen":{"barkeep":6,"merchant":2}},"diary":[[5,"reached level 3 (learned Stray Magnet; learned Sermoniser)"],[6,"reached level 4 (learned Peacemaker)"],[7,"Natasha sings \"The Heron King\" with great conviction. The pitch has gone somewhere else for the night. Echo is very kind about it."],[8,"Natasha settles a row about whose turn it is to cook by inventing a rota. The rota is law now. Somebody asks how. 'Peacemaker,' says Natasha."],[8,"The bag is empty in Goblin Camp, so Natasha roasts a walking-cap on the end of a spear and shares it out. Nobody asks for seconds, and nobody goes hungry."],[9,"Nobody has a ration left in Goblin Camp, so Natasha roasts a walking-cap over the fire. It isn't supper, exactly, but nobody goes to bed hungry."],[9,"reached level 6 (learned Aura of Courage; learned Tooth Puller)"],[10,"The rations ran out in Goblin Camp. Natasha puts a walking-cap on a stick, and that's supper."],[10,"Echo sings \"The Washing-Line Jig\" and loses the tune twice. Each time Christian hands it back.",{"night":"n4","music":true}],[11,"turned 4 goblin ears into 8s in Thornwall"],[11,"bought an Iron-Rimmed Shield from Dagny in Thornwall for 11s"],[11,"had a knuckle flattened on the table by Christian, gently"],[12,"Feast day in Thornwall: Natasha finds a bench at the long tables and eats The Sergeant's Roast with strangers who are friends by the pudding. It comes with the carving shouted out slice by slice. (8 copper)",{"meal":"m16"}],[12,"sold 1 trinket for 10s"],[12,"picked up the Good Dog Tarot in Carrbridge for 12 silver"],[12,"Natasha washes bowls at the Carrbridge poorhouse for two hours. There are always more bowls."],[13,"The Carrbridge cook serves Stolen-Sausage Hotpot on feast day, made from what heroes sold her, and Natasha recognises some of it. It tastes of justice and fennel. (8 copper)",{"meal":"m18"}],[14,"spent a lazy day wandering Ashfen"],[14,"Natasha organises the poorhouse sweepers into a line and calls the beat. Dust flies, and the hall is clean in half the time."],[14,"Natasha tastes an Eel Pie from Widow Marl, then from Tobin the eel-catcher, then from Widow Marl again to be sure, and names Tobin the eel-catcher the better. The other one takes it badly. (1 silver)",{"meal":"m29"}],[14,"talked with Echo about whether a mimic knows it is a chest"],[14,"With nobody else awake, Natasha lays out the Good Dog Tarot and reads for themself: the Three of Cups, the Moon and the Nine of Swords. Not a spread anyone wants.",{"reading":"r33"}],[15,"Natasha preaches to the crew about sharing. Christian hands over the last biscuit, shamed."],[16,"in the lych-gate, on the first floor of the Ashveil Crypts: A little gabled roof over a stone bench. Moss covers everything. The bench has been polished by something that doesn't sit. Nobody sees a pile of bones that rattles until it goes off. Christian throws himself clear. It catches Natasha too. Echo comes off worst of all. The next room hears it."],[16,"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake.",{"meal":"m36"}],[17,"in the crossing of galleries, on the first floor of the Ashveil Crypts: Four galleries meet. In the middle, a stone bench for the tired. A tired thing is sitting on it. Echo counts heads, shakes her head, and they slip past 2 bone constructs, a skeleton archer and risen dead for now."],[17,"woke stiff but rested in the crossing of galleries, and counted it a win"],[17,"The Three of Cups, Natasha's own cards said three days ago. Natasha has been made welcome somewhere new since.",{"reading":"r33"}],[17,"Gruk's Victory Ham in the Ashveil Crypts. Christian cooks it like a ceremony, and the crew eat it like one. It comes glazed on the warchief's own shield.",{"meal":"m42"}],[17,"reached level 8 (learned Smite; learned Pilgrim)"],[18,"in the iron-bound door, on the first floor of the Ashveil Crypts: A cold fire at the iron-bound door and a name cut into a beam: The Cobalt Storm. Whatever was here went home in their packs."],[18,"listened to the dark breathe in the iron-bound door on the first floor until the watch changed"],[18,"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile.",{"meal":"m51"}],[18,"Christian sews a lucky charm into the lining of Natasha's coat. Natasha only finds it a week later. (Needle and Thread, if anyone's asking.)"],[19,"in the nave, on the second floor of the Ashveil Crypts: Rows of pews, and a patient congregation. As one, they turn their heads. The dark keeps its secrets from Echo. Rubbish, mostly, and some of the rubbish is moving."],[19,"Echo watches the treeline for an hour without moving. Natasha checks she is still breathing. Still as a Heron all the way, Echo insists."],[19,"reached level 10 (became a Paladin; learned Oath of Light)"],[20,"in the funeral feast hall, on the second floor of the Ashveil Crypts: A table laid for forty. The guests stand as one and draw their cutlery. The dark keeps its secrets from Echo. A note in the corner reads 'nothing here, sorry', and it is right."],[20,"slept the whole night through in the funeral feast hall, boots and all"],[20,"Christian tightens a loose strap on Natasha mid-corridor, without asking, without breaking stride."],[20,"Natasha starts \"The Miner's Daughter\", stops, starts again, and decides it was the wrong song.",{"night":"n15","music":true}],[20,"Natasha lays out her pilgrim tokens by the fire and tells Echo where each one came from."],[21,"in the family archive, on the second floor of the Ashveil Crypts: Shelves of deeds in oilcloth. A big family tree on the far wall has been scratched out, one branch at a time. Christian reads the papers. They are all about drainage."],[22,"Echo starts \"The Footbridge Dance\" quietly, and by the chorus Natasha and Christian are singing too.",{"night":"n20","music":true}],[22,"Echo knocks a pine cone off a branch in the dark, by sound alone. Natasha demands to see it again."],[22,"reached level 11 (learned Second Breakfast)"],[23,"Natasha has a Drake Steak at The Damp Lantern and sends compliments to Gilda Wetfoot. It makes the eater breathe tiny smoke rings. (3 silver 6 copper)",{"meal":"m63"}],[23,"Natasha settles an Ashfen boundary dispute over a hedge. The hedge is split, fairly. That's Peacemaker for you."],[24,"It's feast day in Ashfen, and Echo, Natasha and Christian eat some Fen-Mist Chowder at the long tables with half the town. It smells of smoke and the fen at dawn. (8 copper each)",{"meal":"m68"}],[24,"The market in Ashfen has a cook up from Saltmarrow today. Natasha queues for some Sea-Grape Salad on the strength of the smell alone. It pops so loudly someone checks the dark. (2 silver 4 copper)",{"meal":"m70"}],[24,"In the Ashfen feud over how many eels should look out of a pie, Natasha is the deciding spoon this week. The vote goes to Widow Marl. (1 silver)",{"meal":"m71"}],[24,"Natasha talks two angry farmers out of a fight at the Ashfen tavern, and both buy Natasha a drink. Somebody asks how. 'Peacemaker,' says Natasha."],[25,"Old Marrow lays three cards out for Natasha at a lean-to behind the undertaker's: Justice upside down, the Empress and the King of Cups. Old Marrow taps the middle card and says nothing.",{"reading":"r102"}],[25,"Natasha offers to check the crew's teeth by firelight. Christian refuses. Natasha will get to Christian eventually."],[26,"Natasha sorts out a farmer's toothache at a field gate and is paid in eggs. Tooth Puller at work, though Natasha would never say so."],[26,"Natasha cooks some Walking-Cap Ragout in Bleakmarsh while the rest pretend to keep watch. It stopped twitching the moment the garlic went in.",{"meal":"m80"}],[27,"Christian passes Natasha a strip of dried apple without a sound. They share the waiting, and the apple, and the thing that comes after, which is nothing."],[27,"Natasha shares supper with two pilgrims and their goat. The goat eats Christian's bootlace. Natasha learned that one as The Pilgrims' Escort, and it shows."],[28,"Natasha strips off the boots and wades. The cold is a living thing, and the far bank is an untouched stretch of game country.",{"road_rec":"r130"}],[28,"put on Sunflash Sigil, a gift from Ankit"]],"events":[{"id":"e12","day":1,"season":1,"sday":1,"kind":"join","imp":1,"text":"Natasha joins the league: a pink-clad Warrior, arriving in Ironhaven with 30 silver and a rusty sword, and an old map of Goblin Camp.","heroes":["h11"],"parties":[],"loc":"ironhaven"},{"id":"e27","day":1,"season":1,"sday":1,"kind":"odd_job","imp":2,"text":"Waiting on company that hasn't come, Natasha keeps busy throwing out a drunk who turned out to be the mayor's cousin for Madame Ostrava. It pays 10 silver.","heroes":["h11"],"parties":[],"loc":"ironhaven"},{"id":"e42","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Echo and Natasha shake on it at The Gilded Flagon: they are now The Verdant Sigil. (Honorable, by the look of them.)","heroes":["h6","h11"],"parties":["p2"],"loc":"ironhaven"},{"id":"e50","day":1,"season":1,"sday":1,"kind":"campfire","imp":2,"text":"Echo offers Natasha the dry side of the tent. Natasha accepts, suspiciously.","heroes":["h6","h11"],"parties":["p2"],"loc":"ironhaven"},{"id":"e85","day":3,"season":1,"sday":3,"kind":"party_join","imp":3,"text":"Christian joins The Verdant Sigil over drinks in Thornwall. That makes 3.","heroes":["h19","h6","h11"],"parties":["p2"],"loc":"thornwall","wx":"rain"},{"id":"e88","day":3,"season":1,"sday":3,"kind":"journey","imp":2,"text":"Christian and The Verdant Sigil share the road to Thornwall. By the second milestone they've agreed on nothing, least of all a shortcut that turned out to be a longcut.","heroes":["h19","h6","h11","h19"],"parties":["p2"]},{"id":"e118","day":5,"season":1,"sday":5,"kind":"keepsake","imp":3,"text":"The old map was right. Natasha stands at the mouth of Goblin Camp, the map in one hand, and every turn of it matches.","heroes":["h11","h6","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e119","day":5,"season":1,"sday":5,"kind":"delve","imp":1,"text":"The Verdant Sigil descends into Goblin Camp, untouched (0%), map in hand.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e120","day":5,"season":1,"sday":5,"kind":"fight","imp":3,"text":"First blood for Echo, Natasha and Christian: The Verdant Sigil makes short work of 4 Goblins and a Giant Rat on floor 1 of Goblin Camp. Loot: 6 goblin ears.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","fight":"f10","foes":["goblin","giant_rat","goblin"],"where":"on floor 1 of Goblin Camp","won":true,"close":false,"wx":"rain"},{"id":"e121","day":5,"season":1,"sday":5,"kind":"night","imp":2,"text":"A hooded stranger shares The Verdant Sigil's fire in Goblin Camp, eats half the stew, and says something very specific about Emberdeep before leaving.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e130","day":5,"season":1,"sday":5,"kind":"levelups","imp":1,"text":"Level-ups: Garrett to 5 (learned Forager; Forager rank 2); Chloe to 4 (learned Quick Shot; learned Called Shot); Echo to 3 (learned Pinning Shot; learned Evasive); Natasha to 3 (learned Stray Magnet; learned Sermoniser); Christian to 3 (learned Almsgiver; learned Local History).","heroes":["h4","h17","h6","h11","h19"],"parties":[]},{"id":"e141","day":6,"season":1,"sday":6,"kind":"fight","imp":1,"text":"The Verdant Sigil makes short work of 2 Goblins and a Goblin Shaman on floor 2 of Goblin Camp. Loot: 5 goblin ears, 3 walking-caps.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","fight":"f14","foes":["goblin","goblin_shaman","goblin"],"where":"on floor 2 of Goblin Camp","won":true,"close":false,"wx":"fog"},{"id":"e153","day":6,"season":1,"sday":6,"kind":"levelups","imp":1,"text":"Level-ups: Yomna to 5 (learned Drain Life; Detect Magic, honed); Mikolaj to 5 (learned Tailwind; learned Pathfinding); Varun to 4 (learned Precision; learned Volley); Echo to 4 (learned Thorn Whip); Natasha to 4 (learned Peacemaker); and 5 more.","heroes":["h10","h16","h3","h6","h11"],"parties":[]},{"id":"e182","day":8,"season":1,"sday":8,"kind":"treasure","imp":3,"text":"First treasure for Natasha, Echo and Christian: on floor 2 of Goblin Camp, a dead adventurer leaves 66 silver and an unidentified relic, which goes to Christian.","heroes":["h11","h6","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"fog"},{"id":"e210","day":9,"season":1,"sday":9,"kind":"boss","imp":5,"text":"Down at the bottom of Goblin Camp, The Verdant Sigil slays Gruk the Warchief, a Goblin Archer and a Goblin. Echo's Pinning Shot dropped Gruk, Christian's Hammer Down tied him up, and Echo did the unglamorous work that kept the line from breaking. Loot: 6 goblin ears, 3 trinkets, Gruk's own smoked ham.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","fight":"f25","foes":["goblin_warchief","goblin_archer","goblin"],"where":"at the bottom of Goblin Camp","won":true,"close":false,"wx":"fog"},{"id":"e211","day":9,"season":1,"sday":9,"kind":"treasure","imp":1,"text":"Gruk the Warchief's hoard, counted twice by torchlight: 3 gold pieces and 2 silver.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","in_fight":"f25","wx":"fog"},{"id":"e212","day":9,"season":1,"sday":9,"kind":"night","imp":2,"text":"Echo's ghost story in Goblin Camp ends with \"...and it was standing right behind them.\" Natasha does not look behind her once, all night.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"fog"},{"id":"e222","day":9,"season":1,"sday":9,"kind":"argument","imp":3,"text":"Whose idea was the last dungeon? Christian and Natasha of The Verdant Sigil settle it with a shouting match.","heroes":["h19","h11"],"parties":["p2"]},{"id":"e227","day":9,"season":1,"sday":9,"kind":"levelups","imp":1,"text":"Level-ups: Kev to 6 (learned Arm Wrestler; learned Ice Wall); Echo to 6 (learned Hunter's Mark; learned Ice Fishing); Natasha to 6 (learned Aura of Courage; learned Tooth Puller); Christian to 6 (learned Carpentry; learned Disarm); Griffin to 5 (Taunt, honed; learned Sentry); and 3 more.","heroes":["h2","h6","h11","h19","h5"],"parties":[]},{"id":"e228","day":9,"season":1,"sday":9,"kind":"big_move","imp":4,"text":"Gruk the Warchief is down, and the table moves: Echo +56 renown (11th to 2nd), Christian +52 (10th to 3rd) and Natasha +51 (12th to 4th). The Verdant Sigil +107 party renown, 3rd to 1st among the crews.","heroes":["h6","h19","h11"],"parties":["p2"],"cause":"e210","moves":[{"hero":"h6","gain":56,"from":11,"to":2},{"hero":"h19","gain":52,"from":10,"to":3},{"hero":"h11","gain":51,"from":12,"to":4}],"party_moves":[{"party":"p2","gain":107,"from":3,"to":1}],"fight":"f25"},{"id":"e229","day":10,"season":1,"sday":9,"kind":"rework","imp":3,"text":"The old tunnels have shifted, say the guild halls: every lair has new rooms and new tenants, and every map drawn before today is waste paper. Every hero gets a torch, and the 13 who held old maps get bought out.","heroes":["h2","h4","h5","h6","h7","h9","h10","h11","h13","h14","h16","h18","h19"],"parties":[]},{"id":"e241","day":10,"season":1,"sday":10,"kind":"delve_done","imp":1,"text":"The Verdant Sigil comes up for air after 6 days, pockets heavier and boots wetter. They got all the way to the bottom, split 236 silver on the way up and turned back because the rations would only just see them home.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","days":6,"bottom":true,"rooms":[],"gold":236,"turn":"supplies","wx":"fog"},{"id":"e281","day":11,"season":1,"sday":11,"kind":"road","imp":3,"text":"On the road to Thornwall, a torn treasure map blows across the path and wraps around Natasha's ankle. It is faded, but Emberdeep is clearly marked.","heroes":["h11","h19","h6"],"parties":["p2"],"road":"goblin_camp~thornwall","road_rec":"r15"},{"id":"e295","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Verdant Sigil settles on a goal: to earn 1,150 silver between them before the season ends. \"Eleven hundred and fifty! We're going to need a bigger purse!\" says Natasha.","heroes":["h6","h11","h19"],"parties":["p2"]},{"id":"e418","day":15,"season":1,"sday":15,"kind":"talent","imp":2,"text":"Natasha preaches to the crew about sharing. Christian hands over the last biscuit, shamed.","heroes":["h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","skill":"sermoniser","wx":"fog"},{"id":"e445","day":15,"season":1,"sday":15,"kind":"campfire","imp":1,"text":"Fourteen days in The Verdant Sigil: Echo and Natasha have learned which of them snores and which of them lies about snoring.","heroes":["h6","h11"],"parties":["p2"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e470","day":16,"season":1,"sday":16,"kind":"delve","imp":1,"text":"The Verdant Sigil lights the first torch at the mouth of the Ashveil Crypts. The place is mostly unexplored (26%).","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e492","day":16,"season":1,"sday":16,"kind":"meet","imp":2,"text":"Echo and Garrett compare boots, then blisters, then regrets, at the Ashveil Crypts.","heroes":["h6","h11","h19","h17","h4"],"parties":["p2","p4"],"loc":"ashveil_crypts"},{"id":"e496","day":16,"season":1,"sday":16,"kind":"cooking","imp":1,"text":"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts","meal":"m36"},{"id":"e499","day":16,"season":1,"sday":16,"kind":"bond","imp":2,"text":"Echo lends Natasha a dry pair of socks and doesn't ask for them back. Out here, that's friendship.","heroes":["h6","h11"],"parties":[],"loc":"ashveil_crypts","bond":"friends"},{"id":"e500","day":16,"season":1,"sday":16,"kind":"campfire","imp":1,"text":"Christian mends Natasha's bootlace with a bit of string and a great deal of confidence.","heroes":["h19","h11"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e507","day":17,"season":1,"sday":17,"kind":"fight","imp":2,"text":"It takes the Verdant Sigil 6 rounds to scrape past 3 Skeletons and Risen Dead in the coffin racks on the first floor of the Ashveil Crypts. Echo took the last shot with Thorn Whip, and it was enough. Natasha never wasted a move, start to finish. Loot: 10 bones, 4 trinkets, 7 crypt-caps.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f49","foes":["skeleton","skeleton","zombie"],"where":"in the coffin racks on the first floor of the Ashveil Crypts","won":true,"close":true,"shape":"close","reworded":-20},{"id":"e529","day":17,"season":1,"sday":17,"kind":"omen_true","imp":2,"text":"The Three of Cups, Natasha's own cards said three days ago. Natasha has been made welcome somewhere new since.","heroes":["h11"],"parties":[],"loc":"ashveil_crypts","reading":"r33"},{"id":"e532","day":17,"season":1,"sday":17,"kind":"cooking","imp":3,"text":"Gruk's Victory Ham in the Ashveil Crypts, glazed on the warchief's own shield: Christian cooks it like a ceremony, and the crew eat it like one.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts","meal":"m42"},{"id":"e536","day":17,"season":1,"sday":17,"kind":"ambition","imp":5,"text":"Four of the realm's towns, and Natasha has set foot in every one this season. It took longer than she'd like to admit. Next on the list: to write a song.","heroes":["h11"],"parties":[],"ambition":"explorer"},{"id":"e572","day":18,"season":1,"sday":18,"kind":"cooking","imp":1,"text":"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts","meal":"m51"},{"id":"e573","day":18,"season":1,"sday":18,"kind":"bond","imp":2,"text":"Christian and Natasha finish each other's complaints now. Friends, the grumbling kind.","heroes":["h19","h11"],"parties":[],"loc":"ashveil_crypts","bond":"friends"},{"id":"e574","day":18,"season":1,"sday":18,"kind":"talent","imp":2,"text":"Christian sews a lucky charm into the lining of Natasha's coat. Natasha only finds it a week later. (Needle and Thread, if anyone's asking.)","heroes":["h19","h11"],"parties":["p2"],"loc":"ashveil_crypts","skill":"tailor"},{"id":"e592","day":19,"season":1,"sday":19,"kind":"evolve","imp":4,"text":"Pilgrim and Smite carry Natasha the Warrior to a new calling: Paladin, armored faith with a mace. First new trick: Radiance.","heroes":["h11"],"parties":[],"cls_from":"warrior","cls_to":"paladin"},{"id":"e594","day":19,"season":1,"sday":19,"kind":"fight","imp":2,"text":"The Verdant Sigil runs into 3 Skeletons and a Skeleton Archer in the choir loft on the second floor of the Ashveil Crypts and comes out on top. The skeleton met Natasha's Smite and lay down for good. Loot: 16 bones.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f52","foes":["skeleton_archer","skeleton","skeleton"],"where":"in the choir loft on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-23},{"id":"e596","day":19,"season":1,"sday":19,"kind":"keystone","imp":2,"text":"Natasha reaches level 10 and becomes The Pilgrims' Escort: on travel days she often sees strangers safely on their way, for silver and experience. It grew out of Sermoniser and Aura of Courage.","heroes":["h11"],"parties":[],"keystone":"pilgrims_escort","ks":"The Pilgrims' Escort","level":10},{"id":"e598","day":19,"season":1,"sday":19,"kind":"fight","imp":2,"text":"It's 3 Skeletons and a Skeleton Archer against the Verdant Sigil in the nave on the second floor of the Ashveil Crypts, and it isn't close. The hit of the day was Echo's Patient Shot on the skeleton. Christian did the quiet, necessary things, and most of the loud ones too. Loot: 14 bones, 2 trinkets.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f53","foes":["skeleton","skeleton_archer","skeleton"],"where":"in the nave on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-24},{"id":"e606","day":19,"season":1,"sday":19,"kind":"song","imp":3,"text":"At The Damp Lantern, a bard with a cracked lute sings \"Natasha, Natasha, Bring the Silver Home\", every verse about what Natasha found in Goblin Camp. Only the lute doesn't join in.","heroes":["h11"],"parties":[],"loc":"ashfen","song":"s19_11"},{"id":"e614","day":19,"season":1,"sday":19,"kind":"talent","imp":1,"text":"Echo watches the treeline for an hour without moving. Natasha checks she is still breathing. Still as a Heron all the way, Echo insists.","heroes":["h6","h11"],"parties":["p2"],"loc":"ashveil_crypts","skill":"still_as_a_heron"},{"id":"e619","day":19,"season":1,"sday":19,"kind":"levelups","imp":1,"text":"Level-ups: Echo to 10 (learned Trapper; became a Sharpshooter; learned Trick Shot); Natasha to 10 (became a Paladin; learned Oath of Light); Christian to 10 (became an Armorer; learned Whetstone); Chloe to 8 (Rain of Arrows, honed).","heroes":["h6","h11","h19","h17"],"parties":[]},{"id":"e627","day":20,"season":1,"sday":20,"kind":"famous_trap","imp":3,"text":"The Ashveil Crypts have a new tenant and The Ninth Step a fresh victim: Christian, with a cracked collarbone, the first it has caught since the change of management.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e628","day":20,"season":1,"sday":20,"kind":"fight","imp":1,"text":"With Natasha hitting hardest, the Verdant Sigil dispatches a Skeleton Archer, Risen Dead and a Skeleton in the funeral feast hall on the second floor of the Ashveil Crypts. Everything after Christian's Hammer Down went right. Oath of Light woke up in Natasha at just the right time. Loot: 8 bones.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f55","foes":["skeleton_archer","zombie","skeleton"],"where":"in the funeral feast hall on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e641","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"Christian tightens a loose strap on Natasha mid-corridor, without asking, without breaking stride.","heroes":["h19","h11"],"parties":["p2"],"loc":"ashveil_crypts","skill":"hammer_and_hold"},{"id":"e643","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"Natasha lays out her pilgrim tokens by the fire and tells Echo where each one came from.","heroes":["h11","h6"],"parties":["p2"],"loc":"ashveil_crypts","skill":"pilgrim"},{"id":"e669","day":21,"season":1,"sday":21,"kind":"night_game","imp":2,"text":"A goblin appears out of nowhere to challenge Echo at checkers, and leaves with the Button Checkers.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts"},{"id":"e684","day":22,"season":1,"sday":22,"kind":"party_life","imp":3,"text":"Echo stopped at the top of the stair down from the second floor and would not be moved, so The Verdant Sigil turns for the surface and a late breakfast.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","nerve":"h6"},{"id":"e685","day":22,"season":1,"sday":22,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts hands The Verdant Sigil back after 7 days, dusty and squinting. They reached the second floor, turned up The Ninth Step, the bell chamber and the reliquary, cleared 13 rooms, put 40% of it on paper, split 123 silver on the way up and turned back when Echo would go no further. Counting every crew that has been down, the Ashveil Crypts is partly explored (48%).","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","days":7,"bottom":false,"rooms":["The Ninth Step","the bell chamber"],"gold":123,"turn":"nerve"},{"id":"e700","day":22,"season":1,"sday":22,"kind":"ability","imp":2,"text":"Natasha and Echo escort a family of travellers past the Ashveil Crypts. Nothing happens, which is the point. They're paid 26 silver for it.","heroes":["h11","h6"],"parties":["p2"],"loc":"ashveil_crypts","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e710","day":22,"season":1,"sday":22,"kind":"bond","imp":4,"text":"Best friends, too: Echo and Natasha. They have matching scars now and refuse to say how.","heroes":["h6","h11"],"parties":[],"loc":"ashveil_crypts","bond":"best friends"},{"id":"e711","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Echo knocks a pine cone off a branch in the dark, by sound alone. Natasha demands to see it again.","heroes":["h6","h11"],"parties":["p2"],"loc":"ashveil_crypts","skill":"trick_shot"},{"id":"e716","day":22,"season":1,"sday":22,"kind":"levelups","imp":1,"text":"Level-ups: Varun to 13 (learned Spice Box); Mark to 13 (learned Local History; Bear Trap, honed); Matt McF to 12 (Judgement, honed); Ankit to 12 (learned Divine Shield); Natasha to 11 (learned Second Breakfast); and 1 more.","heroes":["h3","h18","h12","h14","h11"],"parties":[]},{"id":"e720","day":23,"season":1,"sday":23,"kind":"road","imp":3,"text":"Supper on the road: Marigold sets up the pot, Echo is given the spoon to hold, and the smell makes the miles ahead seem short.","heroes":["h6","h11","h19"],"parties":["p2"],"road":"ashfen~ashveil_crypts","biome":"marsh","traveller":"marigold","road_rec":"r97"},{"id":"e723","day":23,"season":1,"sday":23,"kind":"sale","imp":1,"text":"Natasha turns 3 trinkets, 1 gem into 52 silver at an Ashfen trader's, after a short and friendly argument.","heroes":["h11"],"parties":[],"loc":"ashfen","amount":52},{"id":"e741","day":23,"season":1,"sday":23,"kind":"song","imp":2,"text":"The keeper of The Damp Lantern puts \"Natasha, Natasha, Bring the Silver Home\" on for Natasha and won't take money for the drinks while it plays.","heroes":["h11"],"parties":[],"loc":"ashfen","song":"s19_11"},{"id":"e758","day":24,"season":1,"sday":24,"kind":"cooking","imp":2,"text":"It's feast day in Ashfen, and Echo, Natasha and Christian eat some Fen-Mist Chowder at the long tables with half the town. It smells of smoke and the fen at dawn. (8 copper each)","heroes":["h6","h11","h19"],"parties":[],"loc":"ashfen","meal":"m68"},{"id":"e790","day":25,"season":1,"sday":25,"kind":"contract","imp":2,"text":"The Verdant Sigil takes a clearing job in Ashfen: 10 will-o'-wisps out of Bleakmarsh by day 3 of next season.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashfen"},{"id":"e808","day":25,"season":1,"sday":25,"kind":"boss_race","imp":2,"text":"The Verdant Sigil is out of the race for Vessimir the Unburied: they have taken a clearing job in Bleakmarsh. That leaves The Royal Vigil.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e823","day":26,"season":1,"sday":26,"kind":"fight","imp":1,"text":"In Bleakmarsh, 2 Will-o'-Wisps get in the Verdant Sigil's way, briefly. The others will tell it differently, but the fight changed on Christian's Hammer Down. Echo's Ambush looked after itself, and the fight with it. Loot: 2 bottled wisplight.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"bleakmarsh","fight":"f64","foes":["wisp","wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-15},{"id":"e825","day":26,"season":1,"sday":26,"kind":"night","imp":2,"text":"A soldier with old wounds sits at The Verdant Sigil's fire in Bleakmarsh and talks about Goblin Camp until the fire is ash. He was there once. He won't say when.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"bleakmarsh"},{"id":"e837","day":26,"season":1,"sday":26,"kind":"bond","imp":1,"text":"Natasha and Mark only met today. You would not guess it. Friends already.","heroes":["h11","h18"],"parties":[],"bond":"friends"},{"id":"e838","day":26,"season":1,"sday":26,"kind":"bond","imp":3,"text":"One look was enough: Natasha recognised a kindred spirit in Varun and moved her pack to his table. Friends from the start.","heroes":["h11","h3"],"parties":[],"bond":"friends"},{"id":"e839","day":26,"season":1,"sday":26,"kind":"meet","imp":2,"text":"With The Verdant Sigil and The Azure Stallions sharing a fire in Bleakmarsh, the watches split nicely and everyone sleeps a little better.","heroes":["h6","h11","h19","h3","h12","h14","h18"],"parties":["p2","p5"],"loc":"bleakmarsh"},{"id":"e840","day":26,"season":1,"sday":26,"kind":"talent","imp":2,"text":"Natasha sorts out a farmer's toothache at a field gate and is paid in eggs. Tooth Puller at work, though Natasha would never say so.","heroes":["h11"],"parties":["p2"],"loc":"bleakmarsh","skill":"tooth_puller"},{"id":"e849","day":26,"season":1,"sday":26,"kind":"epithet","imp":3,"text":"A name that sticks: Natasha Everyone's-Friend. Natasha pretends to hate it.","heroes":["h11"],"parties":[]},{"id":"e877","day":27,"season":1,"sday":27,"kind":"ability","imp":2,"text":"A pedlar with a bad leg and a worse donkey asks Natasha to walk with them past Bleakmarsh. Natasha carries the donkey's load half the way, learns a lot about pots, and is paid 24 silver at the gate.","heroes":["h11"],"parties":["p2"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e882","day":27,"season":1,"sday":27,"kind":"talent","imp":1,"text":"Natasha shares supper with two pilgrims and their goat. The goat eats Christian's bootlace. Natasha learned that one as The Pilgrims' Escort, and it shows.","heroes":["h11","h19"],"parties":["p2"],"loc":"bleakmarsh","skill":"pilgrims_escort"},{"id":"e909","day":28,"season":1,"sday":28,"kind":"song","imp":1,"text":"\"Natasha, Natasha, Bring the Silver Home\" is being sung in six towns now. Bards are fighting over the rights.","heroes":["h11"],"parties":[],"loc":"hollowood","song":"s19_11"},{"id":"e911","day":28,"season":1,"sday":28,"kind":"gift","imp":4,"text":"Sunflash Sigil was Mark's gift to Ankit. Ankit passes it on to Natasha, who can use it, and Mark would approve.","heroes":["h14","h11"],"parties":["p2","p5"],"loc":"bleakmarsh"},{"id":"e916","day":28,"season":1,"sday":28,"kind":"argument","imp":2,"text":"Echo and Natasha are not speaking. It's about whether a goblin counts as a person for tipping purposes. It's never really about whether a goblin counts as a person for tipping purposes.","heroes":["h6","h11"],"parties":["p2"]}],"rels":[{"hero":"h6","score":87,"bond":"best friends","mentor":null,"mate":true},{"hero":"h19","score":80,"bond":"friends","mentor":null,"mate":true},{"hero":"h18","score":75,"bond":"friends","mentor":null,"mate":false},{"hero":"h3","score":70,"bond":"friends","mentor":null,"mate":false},{"hero":"h12","score":58,"bond":null,"mentor":null,"mate":false},{"hero":"h4","score":53,"bond":null,"mentor":null,"mate":false},{"hero":"h17","score":49,"bond":null,"mentor":null,"mate":false},{"hero":"h14","score":47,"bond":null,"mentor":null,"mate":false}],"debts":[],"season":{"kills":5,"bosses":1,"gold_earned":266,"dmg":457,"healed":35,"fights":8,"wins":8,"fled":0,"downed":0,"levels":10,"loot_sold":70,"days_worked":0,"delves":2,"floors":4,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":0,"contracts":0,"travel_days":10,"renown":48.0,"corpses_sold":0,"best_sale":32,"deaths_witnessed":0,"gambled":0,"bounties":12,"best_day":51,"taken":107,"steady":0.0,"deeds":2.0,"band_delves":1.333,"band_floors":2.666,"band_kills":6.666,"deed:hunt":2},"season_closed":false,"career":{"kills":5,"bosses":1,"gold_earned":266,"dmg":457,"healed":35,"fights":8,"wins":8,"fled":0,"downed":0,"levels":10,"loot_sold":70,"days_worked":0,"delves":2,"floors":4,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":0,"contracts":0,"travel_days":10,"renown":48.0,"corpses_sold":0,"best_sale":32,"deaths_witnessed":0,"gambled":0,"bounties":12,"best_day":51,"taken":107,"steady":0.0,"deeds":2.0,"band_delves":1.333,"band_floors":2.666,"band_kills":6.666,"deed:hunt":2},"past":[],"profile":{"maxhp":116,"pow":38.0,"arm":6.0,"acc":86,"eva":12,"crit":9,"spd":8,"resolve":42,"thorns":0,"vs_big":0,"vs":{},"onhit":[["blind",1,0.15]],"lifesteal":0.0,"mind_stat":13,"heart_stat":17,"might":15},"town_rep":{"ironhaven":2,"thornwall":3,"carrbridge":1,"ashfen":15},"regular":{"ironhaven":1,"thornwall":1,"ashfen":3},"jobs":{},"remains_of":[],"death_cause":null,"death_place":null,"buried":null,"memorial_at":null,"body":null,"quiz":["Natasha","Natasha",1,2,1,1,0,7,0,0,5,0,0,2,2,4,6,0,4,2,1],"ambition":"to write a song","ambitions_done":["to set foot in four of the realm's towns in one season"],"visited":["ironhaven","thornwall","carrbridge","ashfen"],"tonight":{"setting":"camp","room":null,"biome":"marsh","road":false,"floor":null,"theme":null,"host":null,"others":[],"place":"Camped out at Bleakmarsh","cast":[{"id":"h11","lines":["Echo and I had a proper falling out. Ugh. But okay!","Camping is the {slam}BEST{/}.","{wave}Ghost stories!{/} Who's first?","This season we're out to earn 1,150 silver between us before the season ends: 360 of 1,150 silver.","One day I'm going to write a song! Wait and see!","Nobody mention fire tonight.","I miss throwing parties.","Echo is my favourite!"],"pet":[]},{"id":"h6","lines":["Natasha and I had a proper falling out. I need to sit down.","I'm not sleeping. I'll just lie here.","{shake}What was that?{/} Did you hear that?","This season we're out to earn 1,150 silver between us before the season ends: 360 of 1,150 silver.","I want to have four true friends. Is that silly?","Nobody mention deep water tonight.","I miss flea markets.","Natasha has my back."],"pet":[]},{"id":"h19","lines":["Keep the fire low.","We move at dawn.","This season we're out to earn 1,150 silver between us before the season ends: 360 of 1,150 silver.","The plan hasn't changed: I'm going to hold a record in the Creel Book.","I miss hiking.","Echo has my back."],"pet":[]}],"talk":[[{"id":"h11","text":"Teach me that Hunter's Mark of yours, Echo."},{"id":"h6","text":"Me? Really? Okay. Maybe."}],[{"id":"h19","text":"Could you teach me Smite?"},{"id":"h11","text":"You just sort of... go WHOOSH."}],[{"id":"h19","text":"Teach me that Hunter's Mark of yours, Echo."},{"id":"h6","text":"If I think about it, I can't."}]],"mounts":[],"wagon":null},"gods":{"stance":"keeps","patron":"aurel","devoted":null,"line":"Prays to all of them, Aurel most of all, though the Antlered has been warming to Natasha lately.","because":null,"cold":null,"row":[{"god":"aurel","word":"doted on","why":"likes"}],"ring":[{"god":"aurel","word":"doted on"},{"god":"pell","word":"watching"},{"god":"brannock","word":"indifferent"},{"god":"marrow","word":"indifferent"},{"god":"tally","word":"indifferent"},{"god":"antlered","word":"watching"},{"god":"gorm","word":"indifferent"},{"god":"mab","word":"fond"},{"god":"veiled","word":"fond"},{"god":"ferryman","word":"indifferent"}],"ask":null,"token":null,"mark":null,"timeline":[],"tally":{"asks_met":0,"kindnesses":0,"wraths":0,"artifacts":0},"share":null,"news":[],"unmasked":null,"badge":null}};